import React from 'react';
import Sidebar from './Sidebar';

const MobileMenu = ({ mobileMenuOpen, setMobileMenuOpen, location, onLogout }) => {
  if (!mobileMenuOpen) return null;

  return (
    <>
      <div
        className="fixed inset-0 bg-black/50 z-40 lg:hidden"
        onClick={() => setMobileMenuOpen(false)}
      ></div>

      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white/95 dark:bg-neutral-900/95 backdrop-blur-xl border-r border-neutral-200/50 dark:border-neutral-800/50 transform transition-transform duration-300 translate-x-0 lg:hidden`}>
        <Sidebar sidebarOpen={true} location={location} onLogout={() => { setMobileMenuOpen(false); if (onLogout) onLogout(); }} />
      </aside>
    </>
  );
};

export default MobileMenu;
